import { notifyDaemonSessionStarted } from '@/daemon/controlClient';
import { logger } from '@/ui/logger';

type ResumeThreadSession = {
    readonly sessionId: string;
    updateMetadata: (handler: (currentMetadata: any) => any) => void;
    sendSessionEvent: (event: { type: 'message'; message: string }) => void;
};
... (later) ...
        opts.session.updateMetadata((currentMetadata) => {
            const updated = { ...currentMetadata, codexThreadId: resumedThread.threadId };
            notifyDaemonSessionStarted(opts.session.sessionId, updated).catch(err => logger.debug(`[resumeExistingThread]: Failed to update daemon with codexThreadId: ${err}`)); return updated;
        });
